pm.test("Discount calculation is correct", function () {
    const bill = pm.response.json().bill;
    const expectedDiscount = bill.subtotal >= 1000
        ? bill.subtotal * 0.10 : 0;

    pm.expect(bill.discount).to.equal(expectedDiscount);
});

pm.test("GST calculation is correct", function () {
    const bill = pm.response.json().bill;
    const taxableAmount = bill.subtotal - bill.discount;

    pm.expect(bill.gst).to.equal(
        Number((taxableAmount * 0.05).toFixed(2))
    );
});

pm.test("Final amount is correct", function () {
    const bill = pm.response.json().bill;
    const expected = bill.subtotal - bill.discount + bill.gst;

    pm.expect(bill.final_amount).to.equal(
        Number(expected.toFixed(2))
    );
});

